using System;using System.Collections.Generic;
namespace PhotoBooth.Customer.UI.Workflow { public sealed class CustomerWorkflowStateMachine { readonly Dictionary<CustomerWorkflowState,HashSet<CustomerWorkflowState>> allowed=new Dictionary<CustomerWorkflowState,HashSet<CustomerWorkflowState>>{{CustomerWorkflowState.Idle,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Countdown}},{CustomerWorkflowState.Countdown,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Smile,CustomerWorkflowState.Idle}},{CustomerWorkflowState.Smile,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Capturing,CustomerWorkflowState.Idle}},{CustomerWorkflowState.Capturing,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.InterShotDelay,CustomerWorkflowState.Preview,CustomerWorkflowState.Idle}},{CustomerWorkflowState.InterShotDelay,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Countdown,CustomerWorkflowState.Idle}},{CustomerWorkflowState.Preview,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Countdown,CustomerWorkflowState.FrameSelection,CustomerWorkflowState.Idle}},{CustomerWorkflowState.FrameSelection,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Preview,CustomerWorkflowState.MotionPhotoSelection,CustomerWorkflowState.Printing,CustomerWorkflowState.Idle}},{CustomerWorkflowState.MotionPhotoSelection,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.FrameSelection,CustomerWorkflowState.Printing,CustomerWorkflowState.Idle}},{CustomerWorkflowState.Printing,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.FrameSelection,CustomerWorkflowState.MotionPhotoSelection,CustomerWorkflowState.Complete,CustomerWorkflowState.Idle}},{CustomerWorkflowState.Complete,new HashSet<CustomerWorkflowState>{CustomerWorkflowState.Idle}}};public CustomerWorkflowState State{get;private set;}=CustomerWorkflowState.Idle;public event EventHandler StateChanged;public void MoveTo(CustomerWorkflowState next){if(next==State)return;if(!allowed[State].Contains(next))throw new InvalidOperationException("Invalid customer workflow transition: "+State+" -> "+next);State=next;StateChanged?.Invoke(this,EventArgs.Empty);}public void RecoverToIdle(){State=CustomerWorkflowState.Idle;StateChanged?.Invoke(this,EventArgs.Empty);}public void ResetToIdleQuiet(){State=CustomerWorkflowState.Idle;} } }
